steps.run:
$ErrorActionPreference = 'Stop'
foreach ($guard in @('check_scope.py', 'check_ci.py')) {
  if (-not (Test-Path -LiteralPath (Join-Path 'trusted/scripts/project' $guard))) {
    throw 'BOOTSTRAP_REVIEW_REQUIRED: the trusted target base needs maintainer review.'
  }
}

$ErrorActionPreference = 'Stop'
$eventData = Get-Content -LiteralPath $env:EVENT_PATH -Raw | ConvertFrom-Json
if ($null -eq $eventData.pull_request) { throw 'A pull request event is required.' }
& python -B trusted/scripts/project/check_scope.py --repo candidate --event $env:EVENT_PATH
if ($LASTEXITCODE -ne 0) { throw 'Declared scope is invalid or needs coordination review.' }
& python -B trusted/scripts/project/check_ci.py --repo candidate --secrets --event $env:EVENT_PATH
if ($LASTEXITCODE -ne 0) { throw 'Secret guard failed.' }
& python -B trusted/scripts/project/check_ci.py --repo candidate --workflow
if ($LASTEXITCODE -ne 0) { throw 'Workflow policy failed.' }
